tiles.query:
let Latest = AIQSnapshotRunsV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2')
| sort by ReportDate desc, SnapshotOrder desc
| take 1;
let SelectedRunIds = toscalar(Latest | summarize make_set(FrameworkRunId));
AIQCategoryChangesV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2', SelectedRunIds)
| project ReportDate, TestCategory = Category, StoredScore = case(Category == 'Baseline', '—', not(CategoryAvailable), 'Unavailable', isnull(CategoryScore), 'N/A', tostring(CategoryScore)), C_E = iff(CategoryAvailable and Category != 'Baseline', strcat(C, '/', E), ''), Miss = M, Noise = N, Duplicate = D, Scored_Planned = iff(not(CategoryAvailable), '', iff(Category == 'Baseline', strcat(ScoredBaselines, '/', PlannedBaselines), strcat(ScoredIssues, '/', PlannedIssues))), ExcludedUnits, Availability, PreviousDate, PreviousStoredScore = case(Category == 'Baseline', '—', not(coalesce(PreviousCategoryAvailable, false)), 'Unavailable', isnull(PreviousCategoryScore), 'N/A', tostring(PreviousCategoryScore)), CategoryComparisonNote
| order by TestCategory asc

let Selected = AIQSnapshotRunsV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2')
| sort by ReportDate desc, SnapshotOrder desc
| take 1;
let SelectedRunIds = toscalar(Selected | summarize make_set(FrameworkRunId));
let Latest = materialize(AIQSnapshotChangesV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2', SelectedRunIds));
union
(Latest | project Metric = 'C — detected issues', Previous = PreviousCorrect, Current = CorrectIssues, Change = DeltaCorrect, PreviousWeighted = real(null), CurrentWeighted = real(null)),
(Latest | project Metric = 'M — missed scored issues', Previous = PreviousMissed, Current = MissedIssues, Change = DeltaMissed, PreviousWeighted = PreviousWeightedMisses, CurrentWeighted = WeightedMisses),
(Latest | project Metric = 'N — Noise cards', Previous = PreviousNoise, Current = NoiseCards, Change = DeltaNoise, PreviousWeighted = PreviousWeightedNoise, CurrentWeighted = WeightedNoise),
(Latest | project Metric = 'D — Duplicate cards', Previous = PreviousDuplicates, Current = DuplicateCards, Change = DeltaDuplicates, PreviousWeighted = PreviousWeightedDuplicates, CurrentWeighted = WeightedDuplicates)
| extend WeightedChange = CurrentWeighted - PreviousWeighted
| order by Metric asc

let Selected = materialize(AIQSnapshotRunsV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2', true)
| where ReportDate >= startofday(_startTime)
| where isempty(_snapshot) or FrameworkRunId == _snapshot
| sort by ReportDate desc, SnapshotOrder desc
| take 1);
let CurrentRun = toscalar(Selected | project FrameworkRunId);
let RunIds = coalesce(toscalar(Selected | project pack_array(FrameworkRunId, PreviousRunId)), dynamic([]));
AIQUnitsV1(RunIds)
| where isempty(_currentAgent) or Agent == _currentAgent
| where isempty(_testCategory) or (_testCategory == 'Baseline' and Kind == 'baseline') or (Kind == 'issue' and TestCategory == _testCategory)
| summarize C = sumif(CorrectIssues, Scorable and Kind == 'issue'), E = sumif(ExpectedIssues, Scorable and Kind == 'issue'), N = sumif(NoiseCards, Scorable), D = sumif(DuplicateCards, Scorable), ExcludedUnits = countif(not(Scorable)), Issues = countif(Scorable and Kind == 'issue'), PlannedIssues = countif(Kind == 'issue'), Baselines = countif(Scorable and Kind == 'baseline'), PlannedBaselines = countif(Kind == 'baseline') by Agent, FrameworkRunId, ReportDate
| project Agent, Snapshot = iff(FrameworkRunId == CurrentRun, 'Current', 'Previous'), ReportDate, C_E = iff(PlannedIssues > 0, strcat(C, '/', E), ''), M = iff(PlannedIssues > 0, E - C, long(null)), N, D, IssueCoverage = strcat(Issues, '/', PlannedIssues), BaselineCoverage = strcat(Baselines, '/', PlannedBaselines), ExcludedUnits
| order by Agent asc, ReportDate asc

let Selected = materialize(AIQSnapshotRunsV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2', true)
| where ReportDate >= startofday(_startTime)
| where isempty(_snapshot) or FrameworkRunId == _snapshot
| sort by ReportDate desc, SnapshotOrder desc
| take 1);
let CurrentRun = toscalar(Selected | project FrameworkRunId);
let PreviousRun = toscalar(Selected | project PreviousRunId);
AIQUnitPairV1(CurrentRun, PreviousRun)
| where isempty(_currentAgent) or Agent == _currentAgent
| where isempty(_testCategory) or (_testCategory == 'Baseline' and Kind == 'baseline') or (Kind == 'issue' and (CurrentCategory == _testCategory or PreviousCategory == _testCategory))
| project Agent, LogicalVersion, ExpectedIssueAlias, Kind, PreviousCategory, CurrentCategory, Previous = strcat(PreviousStatus, '; C/E ', PreviousC, '/', PreviousE, '; M/N/D ', PreviousM, '/', PreviousN, '/', PreviousD), Current = strcat(CurrentStatus, '; C/E ', C, '/', E, '; M/N/D ', M, '/', N, '/', D), DeltaC, DeltaM, DeltaN, DeltaD, CurrentReasons, PreviousReasons
| order by Agent asc, LogicalVersion asc

let Selected = materialize(AIQSnapshotRunsV1(_startTime, _endTime, 'swedencentral', 'unique-issues-noise-1-duplicate-05-miss-025-v2', true)
| where ReportDate >= startofday(_startTime)
| where isempty(_snapshot) or FrameworkRunId == _snapshot
| sort by ReportDate desc, SnapshotOrder desc
| take 1);
let CurrentRun = toscalar(Selected | project FrameworkRunId);
let RunIds = coalesce(toscalar(Selected | project pack_array(FrameworkRunId, PreviousRunId)), dynamic([]));
AIQFindingsV1(RunIds)
| where isempty(_currentAgent) or Agent == _currentAgent
| where isempty(_testCategory) or (_testCategory == 'Baseline' and Kind == 'baseline') or (Kind == 'issue' and TestCategory == _testCategory)
| extend Snapshot = iff(FrameworkRunId == CurrentRun, 'Current', 'Previous')
| summarize Cards = count() by Snapshot, ReportDate, Agent, LogicalVersion, Kind, TestCategory, Scored, Classification, ExclusionReasons = tostring(ExclusionReasons)
| order by ReportDate asc, Scored asc, Agent asc, LogicalVersion asc, Classification asc
